import{_ as e,k as t,v as n}from"./app-Xgp6P-Ux.js";import{t as r}from"./plugin-vue_export-helper-BDNMzG2s.js";import"./gzh-BO4QB3XE.js";import"./zsxq-BKcsYlFO.js";var i=JSON.parse(`{"path":"/ps/01.html","title":"ps 怎么把矩形变成圆形整张图片变成圆形","lang":"zh-CN","frontmatter":{"title":"ps 怎么把矩形变成圆形整张图片变成圆形","date":"2022-08-04T10:12:56.000Z","author":"AI悦创","isOriginal":true,"category":["PS 笔记"],"tag":["PS 笔记"],"icon":"blog","sticky":false,"star":false,"article":true,"timeline":true,"image":false,"navbar":true,"sidebarIcon":true,"comment":true,"lastUpdated":true,"editLink":true,"backToTop":true,"toc":true,"description":"ps 把图片由方形或者矩形制作成圆形的方法有多种，常见的方法是利用椭圆选框工具，绘制出选区，然后建立图层，删除多余的透明区域后，保存为 png 透明背景格式即可，下面通过截图简单说明操作步骤。 imgimg 1、打开图片之后，右键单击左侧菜单栏上的【矩形选框工具】，弹出的下拉菜单里面，点击选中【椭圆选框工具】， imgimg 2、接下来开始绘制圆形区域...","head":[["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"ps 怎么把矩形变成圆形整张图片变成圆形\\",\\"image\\":[\\"https://bornforthis.cn/gzh.jpg\\",\\"https://bornforthis.cn/zsxq.jpg\\"],\\"datePublished\\":\\"2022-08-04T10:12:56.000Z\\",\\"dateModified\\":\\"2025-04-10T23:49:50.000Z\\",\\"author\\":[{\\"@type\\":\\"Person\\",\\"name\\":\\"AI悦创\\"}]}"],["meta",{"property":"og:url","content":"https://bornforthis.cn/ps/01.html"}],["meta",{"property":"og:site_name","content":"AI悦创-Python一对一辅导"}],["meta",{"property":"og:title","content":"ps 怎么把矩形变成圆形整张图片变成圆形"}],["meta",{"property":"og:description","content":"ps 把图片由方形或者矩形制作成圆形的方法有多种，常见的方法是利用椭圆选框工具，绘制出选区，然后建立图层，删除多余的透明区域后，保存为 png 透明背景格式即可，下面通过截图简单说明操作步骤。 imgimg 1、打开图片之后，右键单击左侧菜单栏上的【矩形选框工具】，弹出的下拉菜单里面，点击选中【椭圆选框工具】， imgimg 2、接下来开始绘制圆形区域..."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:image","content":"https://bornforthis.cn/gzh.jpg"}],["meta",{"property":"og:locale","content":"zh-CN"}],["meta",{"property":"og:updated_time","content":"2025-04-10T23:49:50.000Z"}],["meta",{"property":"article:author","content":"AI悦创"}],["meta",{"property":"article:tag","content":"PS 笔记"}],["meta",{"property":"article:published_time","content":"2022-08-04T10:12:56.000Z"}],["meta",{"property":"article:modified_time","content":"2025-04-10T23:49:50.000Z"}]]},"git":{"createdTime":1669634625000,"updatedTime":1744328990000,"contributors":[{"name":"AndersonHJB","username":"AndersonHJB","email":"cleland1432803776@icloud.com","commits":4,"url":"https://github.com/AndersonHJB"},{"name":"AI悦创","username":"","email":"cleland1432803776@icloud.com","commits":2}],"changelog":[{"hash":"1c35a6532eb53bd6ed2f2afd6f70564646e80c01","time":1744328990000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"去掉head"},{"hash":"cbb3a0f217ea57089ad27386b3127e612324b609","time":1675049774000,"email":"cleland1432803776@icloud.com","author":"AI悦创","message":"update"},{"hash":"610fee0943c20fde9f54fa74b604beca191c1a25","time":1674624916000,"email":"cleland1432803776@icloud.com","author":"AI悦创","message":"remove password"},{"hash":"76989bb701c8ac79bbc7e2e46050c8b08855befd","time":1670605630000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"update"},{"hash":"86c50aa64ad737c1db38d74dbb5ec22bb6c5bbeb","time":1670575429000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"update"},{"hash":"027da62f7fafa8a29d6f7ba006e9bff7ac22acfe","time":1669634625000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"first commit"}]},"readingTime":{"minutes":2.48,"words":744},"filePathRelative":"ps/01.md","excerpt":"<p>ps 把图片由方形或者矩形制作成圆形的方法有多种，常见的方法是利用椭圆选框工具，绘制出选区，然后建立图层，删除多余的透明区域后，保存为 png 透明背景格式即可，下面通过截图简单说明操作步骤。</p>\\n<figure><figcaption>img</figcaption></figure>\\n<p>1、打开图片之后，右键单击左侧菜单栏上的【矩形选框工具】，弹出的下拉菜单里面，点击选中【椭圆选框工具】，</p>\\n<figure><figcaption>img</figcaption></figure>\\n<p>2、接下来开始绘制圆形区域，如果想要正圆，可以按住 Shift 键，如果想要移动圆形选框的位置，加按【空格键】后，鼠标拖拉选框移动即可，全程不要松开鼠标左键，</p>","autoDesc":true}`),a={name:`01.md`};function o(r,i,a,o,s,c){return t(),e(`div`,null,[...i[0]||=[n(`<p>ps 把图片由方形或者矩形制作成圆形的方法有多种，常见的方法是利用椭圆选框工具，绘制出选区，然后建立图层，删除多余的透明区域后，保存为 png 透明背景格式即可，下面通过截图简单说明操作步骤。</p><figure><img src="/assets/1-191112151939-BvXBWVF2.jpg" alt="img" tabindex="0" loading="lazy"><figcaption>img</figcaption></figure><p>1、打开图片之后，右键单击左侧菜单栏上的【矩形选框工具】，弹出的下拉菜单里面，点击选中【椭圆选框工具】，</p><figure><img src="/assets/1-191112151940-ewH4ZdC6.jpg" alt="img" tabindex="0" loading="lazy"><figcaption>img</figcaption></figure><p>2、接下来开始绘制圆形区域，如果想要正圆，可以按住 Shift 键，如果想要移动圆形选框的位置，加按【空格键】后，鼠标拖拉选框移动即可，全程不要松开鼠标左键，</p><figure><img src="/assets/1-191112151940-50-BT-aIF2T.jpg" alt="img" tabindex="0" loading="lazy"><figcaption>img</figcaption></figure><p>3、位置调整好了之后，松开【空格键】，正圆和位置都调整好了之后，先松开鼠标，再松开 Shift，</p><figure><img src="/assets/1-191112151940-51-DbsADVyA.jpg" alt="img" tabindex="0" loading="lazy"><figcaption>img</figcaption></figure><p>4、圆形选区建立之后，下一步是建立新的图层，可以在选区范围内单击右键，下拉菜单里面，点击选择【通过拷贝的图层】，或者使用快捷键 Ctrl+J，</p><figure><img src="/assets/1-191112151940-52-SJ5aYzWn.jpg" alt="img" tabindex="0" loading="lazy"><figcaption>img</figcaption></figure><p>5、新建的选区图层，有大面积的透明区域，这些地方需要裁剪掉，</p><figure><img src="/assets/1-191112151940-53-D_i_6T6s.jpg" alt="img" tabindex="0" loading="lazy"><figcaption>img</figcaption></figure><p>6、点击上端菜单栏上的【图像】，弹出的菜单里面，继续点击【裁切】，弹出的界面上，默认是基于【透明像素】，裁切的位置是【顶、底、左、右】，点击确定，</p><figure><img src="/assets/1-191112151940-54-CvL80P2u.jpg" alt="img" tabindex="0" loading="lazy"><figcaption>img</figcaption></figure><p>7、裁切完成之后的效果如下，保存为 png 格式的图片即可。</p><figure><img src="/assets/1-191112151940-55-BcB61OvU.jpg" alt="img" tabindex="0" loading="lazy"><figcaption>img</figcaption></figure><p>圆形图片的透明部分，保存为 png 或 gif 格式后，显示的时候就是透明的，但保存为 jpg 就为白色了，如有疑问，可以在下方留言。</p><p>欢迎关注我公众号：AI悦创，有更多更好玩的等你发现！</p><details class="hint-container details"><summary>公众号：AI悦创【二维码】</summary><figure><img src="/gzh.jpg" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure></details><div class="hint-container info"><p class="hint-container-title">AI悦创·编程一对一</p><p>AI悦创·推出辅导班啦，包括「Python 语言辅导班、C++ 辅导班、java 辅导班、算法/数据结构辅导班、少儿编程、pygame 游戏开发」，全部都是一对一教学：一对一辅导 + 一对一答疑 + 布置作业 + 项目实践等。当然，还有线下线上摄影课程、Photoshop、Premiere 一对一教学、QQ、微信在线，随时响应！微信：Jiabcdefh</p><p>C++ 信息奥赛题解，长期更新！长期招收一对一中小学信息奥赛集训，莆田、厦门地区有机会线下上门，其他地区线上。微信：Jiabcdefh</p><p>方法一：<a href="http://wpa.qq.com/msgrd?v=3&amp;uin=1432803776&amp;site=qq&amp;menu=yes" target="_blank" rel="noopener noreferrer">QQ</a></p><p>方法二：微信：Jiabcdefh</p></div><figure><img src="/zsxq.jpg" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure>`,21)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};